mapper.update:
UPDATE tb_event_stock
SET available_capacity = available_capacity - #{quantity}
WHERE event_id = #{eventId}
AND available_capacity >= #{quantity}

UPDATE tb_event_stock
SET available_capacity = available_capacity + #{quantity}
WHERE event_id = #{eventId}

mapper.insert:
INSERT INTO tb_event_stock (event_id, available_capacity)
VALUES (#{eventId}, #{capacity})
ON DUPLICATE KEY UPDATE available_capacity = #{capacity}

mapper.select:
SELECT ticket_price AS ticketPrice
FROM tb_event_stock
WHERE event_id = #{eventId, typeHandler=com.unisul.seatreservation.config.UuidBinaryTypeHandler}

